-- Migration: Migrate flashcards schema to BIGINT identity IDs
-- Replaces UUID PKs and FKs with BIGINT GENERATED BY DEFAULT AS IDENTITY

-- Drop existing functions first because of type dependencies
DROP FUNCTION IF EXISTS public.create_flashcard_note_with_cards(uuid, uuid, jsonb, text[]);
DROP FUNCTION IF EXISTS public.submit_card_review(uuid, smallint, integer);
DROP FUNCTION IF EXISTS public.get_study_queue(uuid, integer, integer);

-- Drop dependent tables in reverse order of foreign keys
DROP TABLE IF EXISTS public.card_review_logs CASCADE;
DROP TABLE IF EXISTS public.cards CASCADE;
DROP TABLE IF EXISTS public.flashcard_notes CASCADE;
DROP TABLE IF EXISTS public.card_types CASCADE;
DROP TABLE IF EXISTS public.decks CASCADE;

-- 1. Decks table
CREATE TABLE public.decks (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE DEFAULT auth.uid(),
    parent_id BIGINT REFERENCES public.decks(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    config JSONB NOT NULL DEFAULT '{
        "new_cards_per_day": 20,
        "max_reviews_per_day": 200,
        "learn_steps_minutes": [1, 10],
        "leech_threshold": 8
    }'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 2. Card types schema table
CREATE TABLE public.card_types (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE DEFAULT auth.uid(),
    name TEXT NOT NULL,
    fields_schema JSONB NOT NULL DEFAULT '[{"name": "Front", "label": "Front"}, {"name": "Back", "label": "Back"}]'::jsonb,
    has_reverse BOOLEAN NOT NULL DEFAULT false,
    is_default BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 3. Flashcard notes
CREATE TABLE public.flashcard_notes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE DEFAULT auth.uid(),
    card_type_id BIGINT NOT NULL REFERENCES public.card_types(id) ON DELETE CASCADE,
    fields JSONB NOT NULL DEFAULT '{}'::jsonb,
    tags TEXT[] NOT NULL DEFAULT '{}',
    checksum TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- 4. Generated concrete flashcards
CREATE TABLE public.cards (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE DEFAULT auth.uid(),
    note_id BIGINT NOT NULL REFERENCES public.flashcard_notes(id) ON DELETE CASCADE,
    deck_id BIGINT NOT NULL REFERENCES public.decks(id) ON DELETE CASCADE,
    card_type SMALLINT NOT NULL DEFAULT 0,
    queue_state SMALLINT NOT NULL DEFAULT 0,
    due_date TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    step_index SMALLINT NOT NULL DEFAULT 0,
    interval_days INTEGER NOT NULL DEFAULT 0,
    ease_factor REAL NOT NULL DEFAULT 2.50,
    reps INTEGER NOT NULL DEFAULT 0,
    lapses INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Indexes
CREATE INDEX idx_decks_user_parent ON public.decks(user_id, parent_id);
CREATE INDEX idx_cards_deck_queue_due ON public.cards(deck_id, queue_state, due_date);
CREATE INDEX idx_cards_user_queue_due ON public.cards(user_id, queue_state, due_date);
CREATE INDEX idx_cards_note_id ON public.cards(note_id);
CREATE INDEX idx_flashcard_notes_user ON public.flashcard_notes(user_id);

-- Enable RLS
ALTER TABLE public.decks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.card_types ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.flashcard_notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cards ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY "Users can manage own decks" ON public.decks
    FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can manage own card types" ON public.card_types
    FOR ALL USING (auth.uid() = user_id OR is_default = true)
    WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can manage own notes" ON public.flashcard_notes
    FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can manage own cards" ON public.cards
    FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

-- RPC: create note and generate cards
CREATE OR REPLACE FUNCTION public.create_flashcard_note_with_cards(
    p_deck_id BIGINT,
    p_card_type_id BIGINT,
    p_fields JSONB,
    p_tags TEXT[] DEFAULT '{}'
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_note_id BIGINT;
    v_has_reverse BOOLEAN;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT has_reverse INTO v_has_reverse
    FROM public.card_types
    WHERE id = p_card_type_id AND (user_id = v_user_id OR is_default = true);

    IF v_has_reverse IS NULL THEN
        RAISE EXCEPTION 'Card type schema not found';
    END IF;

    INSERT INTO public.flashcard_notes (user_id, card_type_id, fields, tags)
    VALUES (v_user_id, p_card_type_id, p_fields, p_tags)
    RETURNING id INTO v_note_id;

    -- Card 0: Forward
    INSERT INTO public.cards (user_id, note_id, deck_id, card_type, queue_state, due_date)
    VALUES (v_user_id, v_note_id, p_deck_id, 0, 0, timezone('utc'::text, now()));

    -- Card 1: Reverse (if supported)
    IF v_has_reverse THEN
        INSERT INTO public.cards (user_id, note_id, deck_id, card_type, queue_state, due_date)
        VALUES (v_user_id, v_note_id, p_deck_id, 1, 0, timezone('utc'::text, now()));
    END IF;

    RETURN v_note_id;
END;
$$;

-- RPC: submit review
CREATE OR REPLACE FUNCTION public.submit_card_review(
    p_card_id BIGINT,
    p_rating SMALLINT,
    p_time_taken_ms INTEGER DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_card RECORD;
    v_new_state SMALLINT;
    v_new_interval INTEGER;
    v_new_ease REAL;
    v_due_date TIMESTAMPTZ;
BEGIN
    SELECT * INTO v_card
    FROM public.cards
    WHERE id = p_card_id AND (auth.uid() IS NULL OR user_id = auth.uid())
    FOR UPDATE;

    IF v_card IS NULL THEN
        RAISE EXCEPTION 'Card not found or unauthorized';
    END IF;

    v_new_ease := v_card.ease_factor;
    v_new_state := v_card.queue_state;

    IF p_rating = 1 THEN -- Again
        v_new_interval := 0;
        v_new_state := 3;
        v_due_date := timezone('utc'::text, now() + interval '10 minutes');
        v_new_ease := GREATEST(1.30, v_card.ease_factor - 0.20);
    ELSIF p_rating = 2 THEN -- Hard
        v_new_interval := GREATEST(1, ROUND(COALESCE(v_card.interval_days, 1) * 1.2)::integer);
        v_new_state := 2;
        v_due_date := timezone('utc'::text, now() + (v_new_interval || ' days')::interval);
        v_new_ease := GREATEST(1.30, v_card.ease_factor - 0.15);
    ELSIF p_rating = 3 THEN -- Normal
        IF v_card.interval_days = 0 THEN
            v_new_interval := 1;
        ELSIF v_card.interval_days = 1 THEN
            v_new_interval := 6;
        ELSE
            v_new_interval := ROUND(v_card.interval_days * v_card.ease_factor)::integer;
        END IF;
        v_new_state := 2;
        v_due_date := timezone('utc'::text, now() + (v_new_interval || ' days')::interval);
    ELSE -- Easy (4)
        IF v_card.interval_days = 0 THEN
            v_new_interval := 4;
        ELSE
            v_new_interval := ROUND(v_card.interval_days * v_card.ease_factor * 1.3)::integer;
        END IF;
        v_new_state := 2;
        v_due_date := timezone('utc'::text, now() + (v_new_interval || ' days')::interval);
        v_new_ease := v_card.ease_factor + 0.15;
    END IF;

    UPDATE public.cards
    SET queue_state = v_new_state,
        interval_days = v_new_interval,
        ease_factor = v_new_ease,
        due_date = v_due_date,
        reps = v_card.reps + 1,
        lapses = CASE WHEN p_rating = 1 THEN v_card.lapses + 1 ELSE v_card.lapses END,
        updated_at = timezone('utc'::text, now())
    WHERE id = p_card_id;

    RETURN jsonb_build_object(
        'card_id', p_card_id,
        'new_interval_days', v_new_interval,
        'new_state', v_new_state,
        'due_date', v_due_date
    );
END;
$$;

-- RPC: get study queue
CREATE OR REPLACE FUNCTION public.get_study_queue(
    p_deck_id BIGINT,
    p_limit INTEGER DEFAULT 50,
    p_new_limit INTEGER DEFAULT 20
)
RETURNS TABLE (
    card_id BIGINT,
    note_id BIGINT,
    deck_id BIGINT,
    card_type SMALLINT,
    queue_state SMALLINT,
    due_date TIMESTAMPTZ,
    step_index SMALLINT,
    interval_days INTEGER,
    ease_factor REAL,
    reps INTEGER,
    lapses INTEGER,
    note_fields JSONB,
    note_tags TEXT[],
    card_type_name TEXT,
    card_type_schema JSONB,
    has_reverse BOOLEAN
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    RETURN QUERY
    WITH due_cards AS (
        SELECT c.*
        FROM public.cards c
        WHERE c.deck_id = p_deck_id
          AND c.user_id = auth.uid()
          AND c.queue_state IN (1, 2, 3)
          AND c.due_date <= timezone('utc'::text, now())
        ORDER BY c.due_date ASC
        LIMIT p_limit
    ),
    new_cards AS (
        SELECT c.*
        FROM public.cards c
        WHERE c.deck_id = p_deck_id
          AND c.user_id = auth.uid()
          AND c.queue_state = 0
        ORDER BY c.id ASC
        LIMIT p_new_limit
    )
    SELECT
        combo.id AS card_id,
        combo.note_id,
        combo.deck_id,
        combo.card_type,
        combo.queue_state,
        combo.due_date,
        combo.step_index,
        combo.interval_days,
        combo.ease_factor,
        combo.reps,
        combo.lapses,
        n.fields AS note_fields,
        n.tags AS note_tags,
        ct.name AS card_type_name,
        ct.fields_schema AS card_type_schema,
        ct.has_reverse
    FROM (
        SELECT * FROM due_cards
        UNION ALL
        SELECT * FROM new_cards
    ) combo
    JOIN public.flashcard_notes n ON n.id = combo.note_id
    JOIN public.card_types ct ON ct.id = n.card_type_id;
END;
$$;

-- Permissions and grants
GRANT ALL ON TABLE public.decks TO anon, authenticated, service_role;
GRANT ALL ON TABLE public.card_types TO anon, authenticated, service_role;
GRANT ALL ON TABLE public.flashcard_notes TO anon, authenticated, service_role;
GRANT ALL ON TABLE public.cards TO anon, authenticated, service_role;

GRANT EXECUTE ON FUNCTION public.create_flashcard_note_with_cards TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.submit_card_review TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_study_queue TO anon, authenticated, service_role;
